#!/usr/bin/env python3
"""RF1 phase 3: build the clean-sheet AB1 generator as patched COPIES of the baseline (src/pcb/afe_design.py, src/pcb/afe_layout.py). Every change is a checked
text patch (each must apply exactly once), so the difference from the baseline is this file. The baseline files are never written.
Changes (MODELED; parts from data sheets already in data/seed/datasheets):
 1. J2 (2x6 1.27 mm header) -> FPC12: the rigid-flex hinge exit, 12 SMD lands 0.25 x 1.0 mm at 0.5 mm pitch at the duct-side edge
    (AB1A local x 3.25..8.75, AB1B mirrored, y -16.8: the direction of the 90 deg spine duct from each disc centre).
 2. J1 (1x8 / 1x6 1.27 mm header for the receive-coil leads) -> FPC8 / FPC6 lands for the soldered flex jumper (hot-bar), same west edge.
 3. OPEN_ITEMS 31 (baseline defect, 2026-10-29: the AD7389-4 build biases the OPA2211 inputs at VCM = 1.25 V, below its 2.0 V minimum on a single 5 V
    supply, TI SBOS377L): the amplifier reference becomes VBIAS = REFOUT (2.5 V) buffered by OPA2365 half A (unused in the baseline AD7389 build); the coil
    returns, RG and the blanking switch go to VBIAS (2.5 V: inside 2.0..3.6 V with 0.5 V below and 1.1 V above). The ADC input gets a 1:2 divider
    RAAF 1 k / RB 1 k to GND (AIN+ DC = 1.25 V = VCM, AINx- stays on VCM; AD7389-4 common mode 0.2..2.3 V, absolute -0.1..2.6 V), CAAF 1 nF C0G
    (Thevenin 500 ohm: fc 318 kHz, close to the baseline 360 kHz; 1 nF = 55 x the 18 pF track capacitance). RF 390 -> 820 ohm: stage gain 1 + 820 / 10 = 83,
    / 2 at the divider = 41.5 (baseline 40); OPA2211 GBW 80 MHz at G = 100 -> about 0.96 MHz closed loop (> the filter). Output swing (V-)+0.2..(V+)-0.2 V at
    10 k, +-0.6 V at 600 ohm: 2.5 +- 2.1 V into the 2 k divider -> +-1.05 V differential at the ADC (range +-2.5 V).
 4. OPEN_ITEMS 30: OPA2365 (TI SBOS365G 8.3.3, stable to about 1 nF at unity gain; 10-20 ohm series for larger loads) drives 1 uF through RISA / RISB
    10 ohm outside the loop: VBIAS (CVB 1 uF) and VCM (CVM 1 uF).
 5. J2 pin VCM_OUT exports VBIAS on AB1B (CB1D holds the idle MONO input at the amplifier reference: 2.5 V in RF1).
usage: python3 experiments/RF1_rigidflex/src/ab1/make_rf1_ab1.py  -> writes afe_design.py, afe_layout.py next to this file"""
import os
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.abspath(os.path.join(HERE, "..", "..", "..", ".."))

def patch(s, old, new, label):
    n = s.count(old)
    if n != 1: raise SystemExit(f"patch '{label}': found {n} times (needs exactly 1)")
    return s.replace(old, new)

d = open(os.path.join(ROOT, "src/pcb/afe_design.py")).read()
d = patch(d, '"""\nPF233-AB1 analog receiving board: SINGLE SOURCE OF TRUTH', '"""\nRF1 COPY (experiments/RF1_rigidflex, generated by make_rf1_ab1.py; do not edit). PF233-AB1 analog receiving board: SINGLE SOURCE OF TRUTH', "header")
d = patch(d, 'LIB["HDR1x8"] = hdr(8, 1); LIB["HDR1x6"] = hdr(6, 1); LIB["HDR2x6"] = hdr(6, 2)',
          'LIB["HDR1x8"] = hdr(8, 1); LIB["HDR1x6"] = hdr(6, 1); LIB["HDR2x6"] = hdr(6, 2)\n'
          'def fpc(n, pitch=0.5, w=0.25, h=1.0):\n'
          '    """RF1 flex land row: n SMD lands on F.Cu (hot-bar / rigid-flex exit stand-in), pin 1 at -x"""\n'
          '    x0 = -(n - 1) * pitch / 2\n'
          '    return dict(desc=f"RF1 flex land row {n} x {pitch} mm", fp=f"RF1:FPC_{n}_P{pitch}", pins=[(str(i + 1), str(i + 1), "passive") for i in range(n)],\n'
          '                pads=[(str(i + 1), x0 + i * pitch, 0.0, w, h, "rect") for i in range(n)], body=(n * pitch + 0.5, 1.2, 0.0))\n'
          'LIB["FPC12"] = fpc(12); LIB["FPC8"] = fpc(8); LIB["FPC6"] = fpc(6)', "fpc lib")
d = patch(d, 'add("J1", f"HDR1x{J1N}", f"Antenna harness {J1N}p solder pads 1.27mm", "solder-in ribbon harness (36 AWG)")',
          'add("J1", f"FPC{J1N}", f"RF1 receive-coil flex jumper lands {J1N}p", "hot-bar flex jumper (RF1)")', "J1")
d = patch(d, 'add("J2", "HDR2x6", "Main-board 2x6 1.27mm header", "Samtec FTSH/TMM-106-class 2x6 1.27mm")',
          'add("J2", "FPC12", "RF1 rigid-flex hinge exit 12p", "rigid-flex hinge to CB1D (RF1)")', "J2")
d = patch(d, 'add(f"RF{k}", "R0402", "390", "thin-film 0.1%", channel=ch)', 'add(f"RF{k}", "R0402", "820", "thin-film 0.1%", channel=ch)', "RF")
d = patch(d, 'add(f"RAAF{k}", "R0402", "200", "thin-film 0.1%", channel=ch)',
          'add(f"RAAF{k}", "R0402", "1k", "thin-film 0.1%", channel=ch); add(f"RB{k}", "R0402", "1k", "thin-film 0.1% (RF1 divider)", channel=ch)', "RAAF/RB")
d = patch(d, 'add(f"CAAF{k}", "C0603", "2n2", "C0G 50V", channel=ch)', 'add(f"CAAF{k}", "C0603", "1n", "C0G 50V", channel=ch)', "CAAF")
d = patch(d, '    net("VCM", (f"SW{k}", 2)); net("BLANK", (f"SW{k}", 4))', '    net("VBIAS", (f"SW{k}", 2)); net("BLANK", (f"SW{k}", 4))', "SW->VBIAS")
d = patch(d, 'net("VCM", (f"RG{k}", 2))', 'net("VBIAS", (f"RG{k}", 2))', "RG->VBIAS")
d = patch(d, 'net(f"ADCIN_{ch}", (f"RAAF{k}", 2), (f"CAAF{k}", 1), ("UA1", _ip)); net("GND", (f"CAAF{k}", 2)); net("VCM", ("UA1", _in))',
          'net(f"ADCIN_{ch}", (f"RAAF{k}", 2), (f"RB{k}", 1), (f"CAAF{k}", 1), ("UA1", _ip)); net("GND", (f"CAAF{k}", 2), (f"RB{k}", 2)); net("VCM", ("UA1", _in))', "divider")
d = patch(d, '    if ch != "MONO": net("VCM", ("J1", J1PIN[ch + "-"]))', '    if ch != "MONO": net("VBIAS", ("J1", J1PIN[ch + "-"]))', "coil return")
d = patch(d, '    ref = CFG["spare"][0]; net("VCM", (ref, 5));', '    ref = CFG["spare"][0]; net("VBIAS", (ref, 5));', "spare half")
d = patch(d, 'net("VREF_RAW", ("UB", 3)); net("VREF", ("UB", 2), ("UB", 1))',
          'net("VREF_RAW", ("UB", 3)); net("VBIAS_O", ("UB", 2), ("UB", 1))\n'
          'add("RISA", "R0402", "10", "OPA2365 isolation (SBOS365G 8.3.3), RF1"); add("CVB", "C0603", "1u", "X7R 10V, VBIAS reservoir (RF1)")\n'
          'net("VBIAS_O", ("RISA", 1)); net("VBIAS", ("RISA", 2), ("CVB", 1)); net("GND", ("CVB", 2))', "VBIAS buffer")
d = patch(d, 'net("VCM", ("UB", 6), ("UB", 7), ("CVM", 1))',
          'net("VCM_O", ("UB", 6), ("UB", 7)); add("RISB", "R0402", "10", "OPA2365 isolation (SBOS365G 8.3.3), RF1"); net("VCM_O", ("RISB", 1)); net("VCM", ("RISB", 2), ("CVM", 1))', "VCM iso")
d = patch(d, 'if "VCM_OUT" in J2PIN: net("VCM", ("J2", J2PIN["VCM_OUT"]))', 'if "VCM_OUT" in J2PIN: net("VBIAS", ("J2", J2PIN["VCM_OUT"]))', "export VBIAS")
# 6. +3V3D generated on AB1 (RF1): TI TLV755P 3.3 V LDO (SBVS320D, DBV SOT-23-5: 1 IN, 2 GND, 3 EN, 4 NC, 5 OUT; CIN >= 1 uF, COUT >= 1 uF) from +5VA next to the
#    ADC island; the hinge no longer carries +3V3D (J2 pin 3 becomes a ground between the supplies and SCLK: crosstalk guard, phase 2)
# 7. hinge pin order follows the ADC's digital pin order (CS 18, SDO1 19, SDO2 20, SCLK 22) so the escapes do not cross; a ground between SCLK and BLANK
ORDER_ADC = os.environ.get("RF1_ORDER") == "adc"
d = patch(d, 'j2=["+5VA", "GND", "+3V3D", "GND", "SCLK", "CS", "SDO1", "SDO2", "SDO3", "BLANK", "GND", "GND"]', ('j2=["+5VA", "GND", "GND", "GND", "CS", "SDO1", "SDO2", "SCLK", "GND", "BLANK", "GND", "SDO3"]' if ORDER_ADC else 'j2=["+5VA", "GND", ("GND" if os.environ.get("RF1_LDO", "1") == "1" else "+3V3D"), "GND", "SCLK", "CS", "SDO1", "SDO2", "SDO3", "BLANK", "GND", "GND"]'), "J2 A order")
d = patch(d, 'j2=["+5VA", "GND", "+3V3D", "GND", "SCLK", "CS", "SDO1", "SDO2", "BLANK", "MONO_IN", "VCM_OUT", "GND"]', ('j2=["+5VA", "GND", "GND", "GND", "CS", "SDO1", "SDO2", "SCLK", "GND", "BLANK", "MONO_IN", "VCM_OUT"]' if ORDER_ADC else 'j2=["+5VA", "GND", ("GND" if os.environ.get("RF1_LDO", "1") == "1" else "+3V3D"), "GND", "SCLK", "CS", "SDO1", "SDO2", "BLANK", "MONO_IN", "VCM_OUT", "GND"]'), "J2 B order")
d = patch(d, 'LIB["FPC12"] = fpc(12); LIB["FPC8"] = fpc(8); LIB["FPC6"] = fpc(6)',
          'LIB["FPC12"] = fpc(12); LIB["FPC8"] = fpc(8); LIB["FPC6"] = fpc(6)\n'
          'LIB["LDO5"] = dict(LIB["SW1G66"], desc="TI TLV755P 3.3 V 500 mA LDO, SOT-23-5 DBV (SBVS320D Table 4-1)", pins=[("1", "IN", "power_in"), ("2", "GND", "power_in"), ("3", "EN", "input"), ("4", "NC", "no_connect"), ("5", "OUT", "power_out")])', "LDO lib")
d = patch(d, 'add("CB1", "C0805", "10u", "X7R/X5R 10V"); net("+5VA", ("CB1", 1)); net("GND", ("CB1", 2))',
          'add("CB1", "C0805", "10u", "X7R/X5R 10V"); net("+5VA", ("CB1", 1)); net("GND", ("CB1", 2))\n'
          'if os.environ.get("RF1_LDO", "1") == "1":                                         # RF1_LDO=0: +3V3D through the hinge (baseline), no local LDO\n'
          '    add("ULD", "LDO5", "TLV755P33", "TI TLV75533PDBVR (RF1: local +3V3D)"); add("CLI", "C0402", "1u", "X5R 10V"); add("CLO", "C0402", "1u", "X5R 10V")\n'
          '    net("+5VA", ("ULD", 1), ("ULD", 3), ("CLI", 1)); net("GND", ("ULD", 2), ("CLI", 2), ("CLO", 2)); net("+3V3D", ("ULD", 5), ("CLO", 1))', "LDO parts")
if os.environ.get("RF1_DIFF") == "matched":                                          # option (2026-10-29): routes worse on the D40 discs (12 / 8 open), kept for the record
    # 8. matched differential ADC drive (RF1): AINx- gets the same 1 k / 1 k divider and 1 nF from VBIAS as AINx+ gets from the amplifier output, so the ADC
    #    sees (OUT - VBIAS) / 2 through matched RC networks; the separate VCM reference (RD1 / RD2 / CDF / CVM, OPA2365 half B, RISB) is removed: one analog
    #    reference (VBIAS) instead of two. AD7389-4: AINx- absolute -0.1..2.6 V, common mode 0.2..2.3 V: VBIAS / 2 = 1.25 V. Unused ADC pairs tie to ADCN of channel 1.
    d = patch(d, 'net("GND", (f"CAAF{k}", 2), (f"RB{k}", 2)); net("VCM", ("UA1", _in))',
              'net("GND", (f"CAAF{k}", 2), (f"RB{k}", 2))\n'
              '        add(f"RAN{k}", "R0402", "1k", "thin-film 0.1% (RF1 AIN- divider)", channel=ch); add(f"RBN{k}", "R0402", "1k", "thin-film 0.1% (RF1 AIN- divider)", channel=ch); add(f"CAN{k}", "C0603", "1n", "C0G 50V (RF1)", channel=ch)\n'
              '        net("VBIAS", (f"RAN{k}", 1)); net(f"ADCN_{ch}", (f"RAN{k}", 2), (f"RBN{k}", 1), (f"CAN{k}", 1), ("UA1", _in)); net("GND", (f"RBN{k}", 2), (f"CAN{k}", 2))', "AIN- divider")
    d = patch(d, 'net("VCM", ("UA1", 6), ("UA1", 7))', 'net(f"ADCN_{CH[0]}", ("UA1", 6), ("UA1", 7))', "unused AIND")
    d = patch(d, 'if n_ch == 2: net("VCM", ("UA1", 8), ("UA1", 9))', 'if n_ch == 2: net(f"ADCN_{CH[0]}", ("UA1", 8), ("UA1", 9))', "unused AINC")
    a = d.index('_RDV = "100k" if ADC7 else "10k"'); b_ = d.index('net("VCM", ("RISB", 2), ("CVM", 1))') + len('net("VCM", ("RISB", 2), ("CVM", 1))')
    assert d.count('_RDV = "100k" if ADC7 else "10k"') == 1
    d = d[:a] + 'net("UBB_OUT", ("UB", 6), ("UB", 7)); net("GND", ("UB", 5))                       # RF1: OPA2365 half B unused (follower at GND); the VCM reference is gone' + d[b_:]
# 9. buffer halves swapped (2026-10-29): half B (pins 5-7, the baseline's VCM source and routing) drives the large VBIAS net straight from REFOUT; half A
#    (pins 1-3) drives the small VCM net (REFOUT / 2, AINx- only). Isolation: RISB on VBIAS (CVB), RISA on VCM (CVM).
if os.environ.get("RF1_SWAP") == "1" and os.environ.get("RF1_DIFF") != "matched":   # option, off: routed worse (the LDO then blocks the +3V3D island escapes)
    a = d.index('net("VREF_RAW", ("UB", 3)); net("VBIAS_O", ("UB", 2), ("UB", 1))')
    b_ = d.index('net("VCM", ("RISB", 2), ("CVM", 1))') + len('net("VCM", ("RISB", 2), ("CVM", 1))')
    d = d[:a] + '\n'.join([
        'net("VCM_DIV", ("UB", 3)); net("VCM_O", ("UB", 2), ("UB", 1))                       # RF1: half A = VCM (REFOUT / 2) for the AINx- pins',
        'add("RISA", "R0402", "10", "OPA2365 isolation (SBOS365G 8.3.3), RF1"); net("VCM_O", ("RISA", 1)); net("VCM", ("RISA", 2), ("CVM", 1))',
        '_RDV = "100k"                                                                        # divider on REFOUT (ASSUMPTIONS row 35)',
        'add("RD1", "R0402", _RDV, "thin-film 0.1%"); add("RD2", "R0402", _RDV, "thin-film 0.1%"); add("CDF", "C0402", "100n", "X7R 10V"); add("CVM", "C0603", "1u", "X7R 10V")',
        'net("VREF_RAW", ("RD1", 1)); net("VCM_DIV", ("RD1", 2), ("RD2", 1), ("CDF", 1)); net("GND", ("RD2", 2), ("CDF", 2), ("CVM", 2))',
        'net("VREF_RAW", ("UB", 5)); net("VBIAS_O", ("UB", 6), ("UB", 7))                     # RF1: half B = VBIAS (REFOUT, 2.5 V), the amplifier reference',
        'add("RISB", "R0402", "10", "OPA2365 isolation (SBOS365G 8.3.3), RF1"); add("CVB", "C0603", "1u", "X7R 10V, VBIAS reservoir (RF1)")',
        'net("VBIAS_O", ("RISB", 1)); net("VBIAS", ("RISB", 2), ("CVB", 1)); net("GND", ("CVB", 2))']) + d[b_:]
open(os.path.join(HERE, "afe_design.py"), "w").write(d)

L = open(os.path.join(ROOT, "src/pcb/afe_layout.py")).read()
L = patch(L, '"""PF233-AB1 layout:', '"""RF1 COPY (generated by make_rf1_ab1.py; do not edit). PF233-AB1 layout:', "layout header")
L = patch(L, 'put("J1", -16.4, 0.0, 0); put("J2", 15.6, 0.0, 0)',
          'put("J1", -17.0, 0.0, 90)                                                         # RF1: receive-coil flex jumper lands, west edge\n'
          '_j2 = [float(v) for v in os.environ.get("RF1_J2", "6.0,-16.8" if BOARD == "A" else "-6.0,-16.8").split(",")]\n'
          'put("J2", _j2[0], _j2[1], int(_j2[2]) if len(_j2) > 2 else 0)                       # RF1: hinge exit lands; RF1_J2 = "x,y[,rot]" search override', "J positions")
L = patch(L, '    _r, _dx, _dy = _n.split(":"); _x, _y, _rot, _side = PLACE[_r]; PLACE[_r] = (_x + float(_dx), _y + float(_dy), _rot, _side)',
          '    _r, _dx, _dy = _n.split(":"); _x, _y, _rot, _side = PLACE[_r]; PLACE[_r] = (_x + float(_dx), _y + float(_dy), _rot, _side)\n'
          'for _o in [o for o in os.environ.get("RF1_LATE", "").split(";") if o]:                     # RF1: final positions from autoplace_rf1.py (applied after every other rule)\n'
          '    _f = _o.split(":"); PLACE[_f[0]] = (float(_f[1]), float(_f[2]), int(_f[3]) if len(_f) > 3 else 0, _f[4] if len(_f) > 4 else "F")', "late placement")
L = patch(L, '    put(f"RAAF{k}", 6.6, y); put(f"CAAF{k}", 8.9, y)', '    put(f"RAAF{k}", 6.6, y); put(f"CAAF{k}", 8.9, y); _rb = [float(v) for v in os.environ.get("RF1_RB", "8.9,-1.2").split(",")]; put(f"RB{k}", _rb[0], y + _rb[1])\n'
          '    _an = [float(v) for v in os.environ.get("RF1_AN", "6.6,-1.2,8.9,1.3,11.0,1.3").split(",")]; put(f"RAN{k}", _an[0], y + _an[1]); put(f"CAN{k}", _an[2], y + _an[3]); put(f"RBN{k}", _an[4], y + _an[5])', "RB place")
L = patch(L, 'for ref, (x, y) in REF.items(): put(ref, x, y)',
          'for ref, (x, y) in REF.items(): put(ref, x, y)\n'
          '_RF1 = {"A": dict(RISA=(11.4, 2.4), RISB=(15.3, 9.6), CVB=(16.0, 2.2), ULD=(14.8, -4.2), CLI=(17.2, -4.2), CLO=(14.8, -6.4)), "B": dict(RISA=(6.5, 10.0), RISB=(13.4, 11.4), CVB=(6.5, 15.5), ULD=(14.8, -4.2), CLI=(17.2, -4.2), CLO=(14.8, -6.4))}[BOARD]   # RF1: OPA2365 isolation R + VBIAS reservoir\n'
          'for _o in [o for o in os.environ.get("RF1_PUT", "").split(";") if o]: _f = _o.split(":"); _RF1[_f[0]] = (float(_f[1]), float(_f[2])) + ((int(_f[3]),) if len(_f) > 3 else ())\n'
          'for ref, v in _RF1.items(): put(ref, v[0], v[1], v[2] if len(v) > 2 else 0)', "RF1 parts place")
open(os.path.join(HERE, "afe_layout.py"), "w").write(L)
R = open(os.path.join(ROOT, "src/pcb/afe_ripup.py")).read()
R = patch(R, '"""B9: rip-up and reroute', '"""RF1 COPY (generated by make_rf1_ab1.py; do not edit; runs the RF1 afe_layout.py next to it). B9: rip-up and reroute', "ripup header")
R = patch(R, 'p = subprocess.run([sys.executable, "afe_layout.py", "--route"], env=e, capture_output=True, text=True)',
          'p = subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), "afe_layout.py"), "--route"], env=e, capture_output=True, text=True)', "ripup path")
open(os.path.join(HERE, "afe_ripup.py"), "w").write(R)
E = open(os.path.join(ROOT, "src/pcb/afe_export.py")).read()
E = patch(E, '"""PF233-AB1{A,B} exporter:', '"""RF1 COPY (generated by make_rf1_ab1.py; imports the RF1 afe_design / afe_layout next to it). PF233-AB1{A,B} exporter:', "export header")
# RF1 fix (2026-10-29): the stub test took an SMD pad as a sharp rectangle, so a track end on the rectangle corner counted as "on the pad" although the
# rounded corner (roundrect, radius 0.25 x the short side) leaves it off the copper (CVB.2 on AB1A: 4 um short, KiCad joins it, the independent DRC does not).
# Now an SMD end within one corner radius of the pad edge also gets the stub to the pad centre (a same-net segment that stays on the pad).
E = patch(E, 'if 1e-4 < gp < (0.30 if pd["tht"] else 0.12) and (l, e, pd["ref"], pd["num"]) not in seen:',
          'if (1e-4 < gp if pd["tht"] else (-0.25 * min(pd["w"], pd["h"]) < gp and (abs(e[0] - pd["x"]) > 1e-6 or abs(e[1] - pd["y"]) > 1e-6))) and gp < (0.30 if pd["tht"] else 0.12) and (l, e, pd["ref"], pd["num"]) not in seen:', "export stub corner")
open(os.path.join(HERE, "afe_export.py"), "w").write(E)
print("RF1 AB1 generator written: afe_design.py, afe_layout.py, afe_ripup.py, afe_export.py (patched copies)")
